import {WEATHER,TREE_TYPES} from './environment.js';
import {PIT_STYLES,pitSettings} from './pit-plan.js';
const $=s=>document.querySelector(s);
export function mountDrawStudio(api){
  const tools=$('#editor-tools'),labels={move:'Move',draw:'Points',erase:'Erase',start:'Start line',pan:'Pan',measure:'Calibrate',pit:'Pit route',barrier:'Barrier',sketch:'Freehand',tree:'Trees'};
  for(const [key,symbol] of [['sketch','〰'],['tree','♧']]){const b=document.createElement('button');b.className='tool';b.dataset.tool=key;b.title=key==='tree'?'Place trees (T)':'Sketch road (K)';b.innerHTML=`<i>${symbol}</i>`;tools.append(b);}
  tools.querySelectorAll('[data-tool]').forEach(b=>{b.querySelectorAll('span').forEach(s=>s.remove());const label=document.createElement('b');label.textContent=labels[b.dataset.tool]||b.dataset.tool;b.append(label);});
  const ribbon=document.createElement('section');ribbon.className='create-ribbon';ribbon.setAttribute('aria-label','Circuit drawing controls');ribbon.innerHTML='<div class="ribbon-heading"><div><span class="eyebrow">DRAWING STUDIO</span><strong>Shape your next circuit.</strong></div><div class="ribbon-options"><label><input id="snap-grid" type="checkbox"> Snap</label><select id="snap-distance" aria-label="Snap spacing"><option value="1">1 m</option><option value="5" selected>5 m</option><option value="10">10 m</option></select><button id="fit-drawing" class="outline-button">Fit view</button></div></div><div id="drawing-tools-slot"></div><div class="ribbon-foot"><span id="drawing-instruction"></span><span id="cursor-coordinates">X / Z in meters</span></div>';
  $('.circuit-lifecycle').after(ribbon);$('#drawing-tools-slot').append(tools);
  const weatherLayer=document.createElement('div');weatherLayer.className='canvas-weather';weatherLayer.setAttribute('aria-hidden','true');$('#canvas-wrap').prepend(weatherLayer);
  const panel=document.createElement('section');panel.className='panel-section environment-panel';panel.innerHTML=`<div class="section-heading"><span class="section-num">SCENE</span><h2>Weather & trees</h2><span class="scene-tag" id="tree-count"></span></div><label class="studio-field">Preview weather<select id="scene-weather">${Object.entries(WEATHER).map(([key,v])=>`<option value="${key}">${v.label}</option>`).join('')}</select></label><p class="field-hint">Set the studio mood. Choose game weather in Content Manager.</p><div class="tree-editor"><div class="tree-editor-heading"><span class="tree-symbol">♧</span><b id="tree-selection">Tree brush</b></div><div class="studio-fields"><label class="studio-field">Tree type<select id="tree-type">${Object.entries(TREE_TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="studio-field">Height · meters<input id="tree-height" type="number" min="3" max="18" step=".5" value="8"></label></div><div class="analysis-actions"><button id="plant-tree" class="outline-button">Place trees · T</button><button id="scatter-trees" class="outline-button">Scatter edge trees</button></div><button id="remove-tree" class="tree-remove" hidden>Remove selected tree</button></div><p class="field-hint">Trees appear in 3D and the mod. Move or erase them on the drawing.</p>`;
  const pit=document.createElement('section');pit.className='panel-section pit-design-panel';pit.innerHTML=`<div class="section-heading"><span class="section-num">PITS</span><h2>Pit lane design</h2><span class="scene-tag" id="pit-mode"></span></div><div class="pit-illustration" aria-hidden="true"><div class="pit-road"><span>ENTRY →</span><i></i><span>→ EXIT</span></div><div class="pit-stalls"><b>01</b><b>02</b><b>03</b><b>04</b><b>05</b><b>06</b></div></div><div class="studio-fields"><label class="studio-field">Lane width · meters<input id="pit-width" type="number" min="4" max="10" step=".5"></label><label class="studio-field">Bay side<select id="pit-side"><option value="auto">Auto / outside</option><option value="left">Left</option><option value="right">Right</option></select></label></div><label class="studio-field">Lane finish<select id="pit-finish">${Object.entries(PIT_STYLES).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><div id="pit-design-actions"></div><p id="pit-layout-note" class="pit-layout-note"></p><button id="inspect-pits" class="outline-button">Inspect pits in 3D</button>`;
  $('.reference-section')?.after(pit,panel);if(!pit.isConnected){$('.settings-panel').append(pit,panel);}
  $('#pit-design-actions').append($('.pit-tools'));
  $('#fit-drawing').onclick=api.fitView;const snap=()=>api.setSnap($('#snap-grid').checked,Number($('#snap-distance').value));$('#snap-grid').onchange=snap;$('#snap-distance').onchange=snap;
  $('#scene-weather').onchange=()=>api.updateTrack(t=>t.weather=$('#scene-weather').value);
  $('#plant-tree').onclick=()=>api.setTool('tree');$('#scatter-trees').onclick=()=>api.scatterTrees();$('#remove-tree').onclick=()=>{const i=api.getTree();if(i>=0)api.updateTrack(t=>t.trees.splice(i,1));};
  const editTree=()=>{const height=Number($('#tree-height').value);if(!Number.isFinite(height)||height<3||height>18){api.toast('Tree height must be between 3 and 18 meters.');refresh();return;}const values={type:$('#tree-type').value,height},i=api.getTree();api.setTreeBrush(values);if(i>=0)api.updateTrack(t=>Object.assign(t.trees[i],values));refresh();};$('#tree-type').onchange=editTree;$('#tree-height').onchange=editTree;
  for(const [id,key] of [['pit-width','width'],['pit-side','side'],['pit-finish','style']])$('#'+id).onchange=()=>{const v=key==='width'?Number($('#'+id).value):$('#'+id).value;if(key==='width'&&(!Number.isFinite(v)||v<4||v>10)){api.toast('Pit width must be between 4 and 10 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),[key]:v});};
  $('#inspect-pits').onclick=api.preview;
  function refresh(){const t=api.getTrack(),i=api.getTree(),selected=t.trees?.[i],brush=selected||api.getTreeBrush(),plan=api.getPitPlan(),settings=pitSettings(t);$('#scene-weather').value=t.weather||'sunny';weatherLayer.dataset.weather=t.weather||'sunny';$('.studio').dataset.weather=t.weather||'sunny';$('#tree-count').textContent=`${t.trees?.length||0} / 300`;$('#tree-selection').textContent=selected?`Tree ${i+1}`:'Tree brush';$('#tree-type').value=brush.type;$('#tree-height').value=brush.height;$('#remove-tree').hidden=!selected;$('#pit-width').value=settings.width;$('#pit-side').value=settings.side;$('#pit-finish').value=settings.style;$('#pit-mode').textContent=plan.automatic?'AUTO':'CUSTOM';$('#pit-layout-note').textContent=t.points.length<2?'Draw the road to generate a pit lane.':`${plan.count} fitted bays · ${Math.round(plan.length)} m route${plan.expanded?' · connected parking apron added':''}. Inspect placement in 3D.`;$('.pit-illustration').dataset.finish=settings.style;$('#drawing-instruction').textContent=({move:'Drag handles to refine road, pits, barriers, and trees.',draw:'Click to add points. Click START to close an open road.',sketch:'Drag a stroke. Release to create editable road points.',tree:'Click clear ground to plant. Change tree size in the Scene panel.',pit:'Click entry, service route, and exit points in order.',barrier:'Click a barrier path. Finish it in the barrier panel.',erase:'Click an object or handle to erase. Undo is always available.',pan:'Drag the canvas to explore.',start:'Click the road to move the start line.',measure:'Click two points with a known real distance.'})[api.getTool()]||'';}
  return {refresh};
}
